values ('bbbb0002-0000-4000-8000-000000000017', 'en', null, 'Version Control with Git', 'Track every change, work on features in parallel, and collaborate without stepping on each other by learning how Git stores snapshots and how its everyday commands fit together. Structure adapted from the open Pro Git book and OER Commons materials (CC BY-NC-SA 3.0).', null, 'career', 23, true, 'technology', '{}')
