insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0002-0000-4000-8000-000000000017', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"At its core, a Git commit stores…","options":["only the lines that changed since last time","a full snapshot of your tracked files at that moment","a link to a file on a central server","just the commit message and author"],"answer":1,"explanation":"Git thinks in snapshots: each commit records the complete state of your tracked files, sharing unchanged files by reference - see ''How Git thinks''."},{"prompt":"The command that records staged changes into the repository history is…","options":["git add","git status","git commit","git log"],"answer":2,"explanation":"git add stages, git commit records the staged snapshot into history - see ''Your first repository''."},{"prompt":"Before a file''s changes can be committed, they must first be…","options":["pushed","staged with git add","merged","cloned"],"answer":1,"explanation":"Git has three states: modified, staged, committed. You move changes into staging with git add before committing."},{"prompt":"Creating a new branch called feature and switching to it in one step is done with…","options":["git branch feature","git switch -c feature","git merge feature","git checkout feature"],"answer":1,"explanation":"git switch -c feature creates the branch and moves onto it; plain git branch feature only creates it - see ''Branching, merging, and conflicts''."},{"prompt":"To download a copy of a remote repository for the first time, you use…","options":["git pull","git fetch","git clone","git push"],"answer":2,"explanation":"git clone copies an existing remote repository; pull and fetch update a copy you already have - see ''Working with remotes''."},{"prompt":"A merge conflict happens when…","options":["two branches never touched the same file","the same lines were changed differently on two branches being combined","you forgot to commit","the remote is offline"],"answer":1,"explanation":"Git merges automatically until two branches change the same region of a file in incompatible ways, then it asks you to decide."},{"prompt":"To safely undo a commit that is already shared with others, you should…","options":["delete the repository","use git reset --hard to erase it","use git revert to add a new commit that cancels it","edit history and force push"],"answer":2,"explanation":"git revert makes a new commit that undoes an old one without rewriting shared history - see ''Undoing changes''."},{"prompt":"A .gitignore file is used to…","options":["list collaborators","tell Git which files it should not track","store commit messages","speed up merges"],"answer":1,"explanation":"Patterns in .gitignore keep build output, secrets, and local junk out of version control - see ''Collaboration and good practices''."}]}'::jsonb, null, 10),
  (2, 'Why version control, and how Git thinks', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain what version control buys you, and describe the mental model that makes every later Git command make sense: snapshots and the three states. Warm-up: from the diagnostic, what does a single commit actually store?"},{"heading":"The idea","text":"Version control is a system that records changes to files over time so you can recall any earlier version, see who changed what, and work on parallel lines of development without overwriting each other. Git is a distributed version control system: every clone is a full copy of the entire history, not just the latest files. The key mental model is that Git stores snapshots, not differences. Each commit is a photograph of all your tracked files at that instant; files that did not change are stored once and shared by reference, so snapshots are cheap. Git also organizes your work into three states. A file is modified when you have edited it but not yet marked it for the next snapshot. It is staged when you have marked a modified file to go into your next commit. It is committed when the snapshot is safely stored in your local database. Those three states map to three areas: your working directory, the staging area (also called the index), and the repository. Most of Git is just moving changes between these areas."},{"heading":"Worked examples","text":"Suppose you edit README.md. Running ''git status'' now reports it under ''Changes not staged for commit'' - it is modified. You run ''git add README.md'', and status moves it to ''Changes to be committed'' - it is staged. You run ''git commit -m \"Update README\"'', and the snapshot is stored - it is committed, and status is clean again. Now edit README.md a second time but do not stage it, then run ''git commit -m \"more\"'': the commit ignores the unstaged edit, because commit only records what is in the staging area. That single fact - commit records the staging area, not the working directory - explains a huge share of beginner confusion."},{"heading":"Your turn","text":"1) Is Git centralized or distributed? 2) Name the three states a tracked file can be in. 3) Which command moves a modified file into the staging area? 4) Does ''git commit'' record files that are only modified but not staged? 5) True or false: a commit stores a full snapshot of your tracked files. Answers: 1) Distributed - every clone holds the full history. 2) Modified, staged, committed. 3) git add. 4) No - it records only what is staged. 5) True; unchanged files are shared by reference so it stays efficient."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking Git saves only the lines that changed - it conceptually saves whole snapshots. Mistake: expecting an edit to be committed automatically without staging it first. Exit: (a) What are the three areas changes move between? (b) What does ''git commit'' actually record? Answers: working directory, staging area (index), and repository; the contents of the staging area at commit time."}]}'::jsonb, 'A commit is identified by a 40-character SHA-1 hash, but you can almost always refer to it by its first 7 characters, for example 1f3a9c2.', 13),
  (3, 'Your first repository: init, add, commit, status, log', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Start a repository from scratch, stage and commit changes, read the status of your working tree, and inspect history. Warm-up: which two commands, in order, take a brand-new file and record it into history?"},{"heading":"The idea","text":"You create a repository in an existing folder with ''git init'', which makes a hidden .git directory that holds the entire history. From then on, the daily loop is: edit files, stage them with ''git add'', then record a snapshot with ''git commit''. ''git status'' is your compass: it tells you which files are untracked, modified, or staged. ''git log'' shows the history of commits, newest first, each with its hash, author, date, and message. Two habits pay off immediately: commit small, related changes together, and write a clear message that says what the change does. Before your first commit Git also wants to know who you are, set once with ''git config''."},{"heading":"Worked examples","text":"A full first session looks like this. ''git config --global user.name \"Ada Lovelace\"'' and ''git config --global user.email \"ada@example.com\"'' set your identity. In a project folder, ''git init'' creates the repository. You add a file, then ''git status'' shows notes.txt as untracked. ''git add notes.txt'' stages it; ''git commit -m \"Add project notes\"'' records the first snapshot. Edit the file again, and ''git add notes.txt'' followed by ''git commit -m \"Expand setup steps\"'' records a second. Now ''git log --oneline'' prints a compact history such as ''9c1d2e0 Expand setup steps'' above ''a30f5b1 Add project notes''. To stage everything changed at once you can use ''git add .'', and to see exactly what you changed before staging, ''git diff'' shows the line-by-line differences."},{"heading":"Your turn","text":"1) Which command creates a new repository in the current folder? 2) What does ''git status'' tell you about an untracked file? 3) Write the command to commit staged changes with the message ''Fix typo''. 4) What does ''git log --oneline'' show that plain ''git log'' compresses? 5) Which command shows unstaged changes line by line? Answers: 1) git init. 2) That the file exists but Git is not yet tracking it. 3) git commit -m \"Fix typo\". 4) One commit per line with a short hash and the message. 5) git diff."},{"heading":"Common mistakes & exit ticket","text":"Mistake: running ''git commit'' with nothing staged and being surprised that nothing is recorded. Mistake: forgetting to set user.name and user.email, so early commits carry a confusing or missing author. Exit: (a) What is the everyday three-step loop? (b) Which command is your compass for the working tree''s state? Answers: edit, git add, git commit; git status."}]}'::jsonb, 'Write commit messages in the imperative mood, as if completing the sentence ''If applied, this commit will...'', for example ''Add login form validation''.', 14),
  (4, 'Branching, merging, and resolving conflicts', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Create and switch branches, merge one branch into another, and resolve a merge conflict by hand. Warm-up: from the diagnostic, which single command both creates a branch and switches to it?"},{"heading":"The idea","text":"A branch is a movable pointer to a commit, letting you develop a feature in isolation while the main line stays stable. You create and switch with ''git switch -c name'' (older Git uses ''git checkout -b name''). When the feature is ready, you merge it back. If the target branch has not moved on, Git does a fast-forward, simply sliding the pointer forward. If both branches have new commits, Git makes a merge commit that ties the two histories together. Git merges automatically whenever the two sides changed different parts of the code. A conflict arises only when both branches changed the same lines in incompatible ways. Then Git pauses, marks the clashing region inside the file with conflict markers, and waits for you to choose the final content, stage the fixed file, and complete the merge."},{"heading":"Worked examples","text":"You are on main and run ''git switch -c feature-login''. You commit some work on the login form. Meanwhile main also gained a commit. Back on main, ''git merge feature-login'' now creates a merge commit because both branches advanced. If instead main had not moved, the same command would fast-forward. Now imagine a conflict: both branches edited the same line of app.py. Git stops and the file shows markers like ''<<<<<<< HEAD'', your version, ''======='', the other version, and ''>>>>>>> feature-login''. You edit the file to the single correct result, delete the marker lines, run ''git add app.py'' to mark it resolved, then ''git commit'' to finish the merge. Useful helpers: ''git branch'' lists branches, ''git merge --abort'' backs out of a conflicted merge, and ''git log --graph --oneline'' draws the branch structure."},{"heading":"Your turn","text":"1) What is a branch, in one sentence? 2) Which command creates branch ''bugfix'' and switches to it in one step? 3) When does a merge fast-forward instead of making a merge commit? 4) What three markers does Git insert around a conflicted region? 5) After editing a conflicted file to its final form, what two commands finish the merge? Answers: 1) A movable pointer to a commit. 2) git switch -c bugfix. 3) When the target branch has no new commits of its own, so the pointer can just slide forward. 4) <<<<<<<, =======, and >>>>>>>. 5) git add on the fixed file, then git commit."},{"heading":"Common mistakes & exit ticket","text":"Mistake: leaving conflict marker lines in the file and committing them by accident. Mistake: thinking every merge causes a conflict - conflicts only happen on overlapping edits to the same lines. Exit: (a) Does creating a branch copy your files? (b) What must you do to a conflicted file before you can commit the merge? Answers: no, a branch is just a pointer; edit it to the correct content, remove the markers, and ''git add'' it to mark it resolved."}]}'::jsonb, 'A branch in Git is just a lightweight, movable pointer to a commit; creating one does not copy your files, which is why branching is fast.', 15),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"Git stores each commit as…","options":["a diff against the previous commit","a full snapshot of tracked files, sharing unchanged ones by reference","a patch file emailed to the server","only the commit message"],"answer":1,"explanation":"The snapshot model is the foundation of how Git thinks - unchanged files are shared, so snapshots stay cheap."},{"prompt":"The everyday loop for recording work is…","options":["push, pull, merge","edit, git add, git commit","clone, fetch, rebase","init, log, status"],"answer":1,"explanation":"You edit files, stage with git add, then record the snapshot with git commit."},{"prompt":"''git status'' reports a file you have never tracked as…","options":["staged","committed","untracked","ignored"],"answer":2,"explanation":"A file Git has never recorded shows up as untracked until you ''git add'' it."},{"prompt":"The command that both creates a branch named ''ui'' and switches to it is…","options":["git branch ui","git switch -c ui","git merge ui","git commit ui"],"answer":1,"explanation":"git switch -c ui creates and checks out the branch in one step (older Git: git checkout -b ui)."},{"prompt":"A merge produces a conflict when…","options":["the two branches touched completely different files","both branches changed the same lines in incompatible ways","you forgot to stage","the branch is brand new"],"answer":1,"explanation":"Git merges non-overlapping changes automatically; only overlapping edits to the same region conflict."},{"prompt":"''git log --oneline'' is useful because it…","options":["deletes old commits","shows one compact line per commit with a short hash and message","stages all files","pushes to the remote"],"answer":1,"explanation":"It compresses each commit to a single readable line, ideal for scanning history."}]}'::jsonb, null, 8),
  (6, 'Working with remotes: clone, push, pull, fetch', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Copy a shared repository, send your commits to it, bring down other people''s commits, and understand the difference between fetch and pull. Warm-up: which command do you run once, at the very start, to get a local copy of a repository that lives on a server?"},{"heading":"The idea","text":"A remote is a version of your repository hosted elsewhere, such as on a shared server. ''git clone <url>'' makes a full local copy and automatically names that remote ''origin''. To share your local commits, ''git push'' uploads them to the remote branch. To bring in work others have shared, you have two options. ''git fetch'' downloads new commits from the remote into your local copy but does not change your working branch, letting you inspect them first. ''git pull'' is a convenience that runs fetch and then merges the new commits into your current branch in one step. Because pull changes your files immediately, many teams prefer to fetch, review, and then merge deliberately. Your local repository also keeps remote-tracking branches like ''origin/main'' that remember where the remote was as of your last fetch."},{"heading":"Worked examples","text":"You join a project with ''git clone https://example.com/team/app.git'', which creates a local folder, downloads the full history, and sets ''origin''. You make a commit and share it with ''git push'' (or the first time, ''git push -u origin main'' to set the upstream). A teammate pushes their own work. You run ''git fetch origin'' and then ''git log origin/main --oneline'' to see what arrived without touching your files; satisfied, you run ''git merge origin/main'' to integrate it. On another day you simply run ''git pull'' to fetch and merge in one motion. To see which remotes exist, ''git remote -v'' lists their names and urls."},{"heading":"Your turn","text":"1) What does ''git clone'' do that ''git pull'' does not? 2) What is the default name Git gives the remote you cloned from? 3) Which command sends your local commits to the remote? 4) In plain terms, ''git pull'' equals which two commands run back to back? 5) Why might a team prefer ''git fetch'' over ''git pull''? Answers: 1) Clone creates the local copy from scratch; pull only updates an existing copy. 2) origin. 3) git push. 4) git fetch followed by git merge. 5) Fetch lets them review incoming commits before merging them into their working branch."},{"heading":"Common mistakes & exit ticket","text":"Mistake: expecting ''git fetch'' to change your working files - it only updates remote-tracking branches; you still need to merge. Mistake: force-pushing over a shared branch and erasing teammates'' commits. Exit: (a) What is the difference between fetch and pull? (b) What is ''origin''? Answers: fetch downloads without merging, pull downloads and merges; origin is the default name for the remote you cloned from."}]}'::jsonb, 'The default name for the remote you cloned from is ''origin'', and the default primary branch on most new projects is ''main''.', 14),
  (7, 'Undoing changes, and rebasing versus merging', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Choose the right undo tool - restore, reset, or revert - and explain how rebasing differs from merging when integrating branches. Warm-up: from the diagnostic, which undo command is safe to use on a commit others already have?"},{"heading":"The idea","text":"Git offers several ways to undo, and picking the right one depends on how far the change has gone. ''git restore <file>'' throws away uncommitted edits in your working directory, returning the file to its last committed state. ''git restore --staged <file>'' unstages a file without losing your edits. ''git reset'' moves the current branch pointer to an earlier commit; a soft reset keeps your changes staged, a mixed reset (the default) keeps them unstaged, and a hard reset discards them entirely. ''git revert <commit>'' is different: instead of erasing history, it creates a brand-new commit that undoes the chosen one, which is why it is safe on shared branches. Separately, rebasing and merging both integrate one branch into another. Merging preserves the exact history and adds a merge commit. Rebasing replays your commits on top of another branch, producing a straight, linear history as if you had started from the newest code - cleaner to read, but it rewrites commit identities, so you avoid it on commits you have already shared."},{"heading":"Worked examples","text":"You messed up a file but have not committed: ''git restore app.py'' returns it to the last commit. You staged something by accident: ''git restore --staged app.py'' unstages it while keeping your edits. You want to undo your last local commit but keep the changes to redo them: ''git reset --soft HEAD~1''. You need to cancel a commit that is already pushed: ''git revert a30f5b1'' adds a new commit reversing it, safe for teammates. For integration, suppose your feature branch is behind main. ''git merge main'' creates a merge commit and keeps both lines visible. Alternatively ''git rebase main'' replays your feature commits on top of the current main, giving a clean straight line - just never rebase commits you have already pushed to a shared branch."},{"heading":"Your turn","text":"1) Which command discards uncommitted edits to a single file? 2) How do you unstage a file without losing your changes? 3) What does ''git reset --hard'' do to your changes? 4) Why is ''git revert'' safe on shared history when ''git reset'' is not? 5) What is the main visible difference between merging and rebasing? Answers: 1) git restore <file>. 2) git restore --staged <file>. 3) It discards them entirely, moving the branch and wiping the working changes. 4) Revert adds a new commit rather than rewriting existing ones, so shared history is preserved. 5) Merge keeps both histories and adds a merge commit; rebase replays commits into one straight line."},{"heading":"Common mistakes & exit ticket","text":"Mistake: reaching for ''git reset --hard'' to undo a pushed commit and losing shared history. Mistake: rebasing a branch others are already working from, which rewrites commits they depend on. Exit: (a) Which undo tool is safe on shared branches? (b) What does rebasing do to your commits? Answers: git revert; it replays them on top of another branch, producing a linear history but new commit identities."}]}'::jsonb, 'A safe rule of thumb: rewrite history (reset, rebase, amend) only on commits you have not shared yet; use revert for anything already pushed.', 15),
  (8, 'Collaboration workflows and good practices', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Follow a feature-branch workflow with pull requests and code review, keep noise out of the repository with .gitignore, and mark releases with tags. Warm-up: why should new work usually happen on its own branch rather than directly on main?"},{"heading":"The idea","text":"Most teams use a feature-branch workflow: main always stays deployable, and each piece of work happens on a short-lived branch created from main. When the work is ready, you push the branch and open a pull request (also called a merge request), which is a proposal to merge your branch. Teammates then do code review, reading the changes, leaving comments, and approving or requesting changes before the branch is merged. This catches bugs early and spreads knowledge. Two hygiene habits keep a repository healthy. A .gitignore file lists patterns for files Git should never track - build output, dependency folders, logs, and secrets - so they do not clutter history or leak. Tags mark specific commits as meaningful points, most often releases, using semantic version names like v1.2.0. Good practices tie it together: commit small and often, write clear imperative messages, pull or fetch before starting new work, and never commit secrets."},{"heading":"Worked examples","text":"A typical cycle: ''git switch -c feature-search'' off an up-to-date main, commit your work, then ''git push -u origin feature-search''. On the hosting platform you open a pull request from feature-search into main; a reviewer comments, you push a fixup commit, they approve, and the branch is merged. For hygiene, a .gitignore might contain lines such as ''node_modules/'', ''*.log'', ''.env'', and ''dist/'', keeping dependencies, logs, secrets, and build output out of version control. When you ship, you tag the release: ''git tag -a v1.0.0 -m \"First release\"'' creates an annotated tag, and ''git push origin v1.0.0'' shares it. To list tags you run ''git tag'', and to see which files Git is ignoring you can run ''git status --ignored''."},{"heading":"Your turn","text":"1) In a feature-branch workflow, what state should main always be in? 2) What is a pull request, in one sentence? 3) Name two kinds of files you would list in .gitignore. 4) Which command creates an annotated tag named v2.0.0? 5) Why should you fetch or pull before starting new work? Answers: 1) Deployable and stable. 2) A proposal to merge one branch into another, with a place for review. 3) Any two of: build output, dependency folders, logs, secrets. 4) git tag -a v2.0.0 -m \"...\". 5) So your new branch starts from the latest shared code and avoids needless conflicts later."},{"heading":"Common mistakes & exit ticket","text":"Mistake: committing a secret such as an API key or .env file, which is hard to fully remove once pushed - add it to .gitignore before the first commit. Mistake: piling unrelated changes into one giant commit that is impossible to review. Exit: (a) What file keeps untracked junk and secrets out of the repository? (b) What is the point of code review on a pull request? Answers: .gitignore; to catch bugs early, improve quality, and share knowledge before merging."}]}'::jsonb, 'Patterns in .gitignore are matched against paths in your repository; a trailing slash like ''build/'' matches a directory, and a leading ''*'' like ''*.log'' matches by extension.', 14),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"The command that makes a full local copy of a remote repository is…","options":["git pull","git clone","git fetch","git push"],"answer":1,"explanation":"git clone copies the entire history and sets up ''origin''; pull and fetch update a copy you already have."},{"prompt":"''git pull'' is equivalent to…","options":["git push then git merge","git fetch then git merge","git clone then git commit","git reset then git status"],"answer":1,"explanation":"Pull is a convenience that fetches new commits and then merges them into your current branch."},{"prompt":"To undo a commit that is already pushed and shared, the safe choice is…","options":["git reset --hard","git revert","git clone","git rebase"],"answer":1,"explanation":"git revert adds a new commit that cancels the old one without rewriting shared history."},{"prompt":"Compared with merging, rebasing produces…","options":["a merge commit that shows both lines","a straight, linear history by replaying commits","a deleted branch","an ignored file"],"answer":1,"explanation":"Rebasing replays your commits on top of another branch, giving a clean linear history but new commit identities."},{"prompt":"''git restore --staged notes.txt'' will…","options":["delete the file","unstage the file while keeping your edits","commit the file","push the file"],"answer":1,"explanation":"It removes the file from the staging area without discarding the changes in your working directory."},{"prompt":"A .env file holding secret keys should be…","options":["committed so teammates can read it","listed in .gitignore so Git never tracks it","tagged as a release","pushed to origin immediately"],"answer":1,"explanation":"Secrets belong in .gitignore; committing them exposes credentials and is hard to fully undo once pushed."}]}'::jsonb, null, 8),
  (10, 'Final quiz: putting Git together', 'quiz', '{"questions":[{"prompt":"The three states a tracked file moves through are…","options":["cloned, pushed, pulled","modified, staged, committed","local, remote, origin","added, tagged, ignored"],"answer":1,"explanation":"Modified means edited, staged means marked for the next snapshot, committed means stored - the core model from ''How Git thinks''."},{"prompt":"Which sequence correctly records a new file into history?","options":["git commit then git add","git add then git commit","git push then git add","git status then git log"],"answer":1,"explanation":"You stage with git add, then record the staged snapshot with git commit."},{"prompt":"You run ''git switch -c hotfix''. This…","options":["deletes the hotfix branch","creates the hotfix branch and switches to it","merges hotfix into main","pushes hotfix to origin"],"answer":1,"explanation":"The -c flag creates the branch and moves you onto it in one step."},{"prompt":"During a merge, the markers <<<<<<<, =======, and >>>>>>> indicate…","options":["a successful fast-forward","a region you must resolve by hand","the commit hash","an ignored file"],"answer":1,"explanation":"Git inserts these around a conflicted region; you edit it to the final content, remove the markers, and git add the file."},{"prompt":"''git fetch'' differs from ''git pull'' in that fetch…","options":["also deletes local branches","downloads new commits but does not merge them into your branch","uploads your commits","creates a new repository"],"answer":1,"explanation":"Fetch updates remote-tracking branches only; pull fetches and then merges into your current branch."},{"prompt":"To cancel a commit that teammates have already pulled, you should use…","options":["git reset --hard","git revert","git rebase","git clone"],"answer":1,"explanation":"Revert preserves shared history by adding a new commit that undoes the old one."},{"prompt":"Rebasing a branch you have already pushed to a shared remote is risky because it…","options":["deletes the remote","rewrites commit identities others may depend on","cannot be undone ever","ignores .gitignore"],"answer":1,"explanation":"Rebase replays commits as new ones; rewriting shared history breaks teammates'' copies - rebase only unshared commits."},{"prompt":"A pull request is best described as…","options":["a command that downloads commits","a proposal to merge a branch, with room for code review","a way to delete history","a type of tag"],"answer":1,"explanation":"It proposes merging your feature branch and gives reviewers a place to comment and approve."},{"prompt":"Which belongs in a .gitignore file?","options":["your main source code","build output, logs, and secret files","the commit history","the README"],"answer":1,"explanation":"Ignore generated and sensitive files so they never get tracked or leaked."},{"prompt":"An annotated release tag is created with…","options":["git tag -a v1.0.0 -m \"First release\"","git branch v1.0.0","git commit v1.0.0","git push v1.0.0"],"answer":0,"explanation":"git tag -a NAME -m MESSAGE creates an annotated tag; push it with ''git push origin v1.0.0'' to share it."}]}'::jsonb, null, 12)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0002-0000-4000-8000-000000000017' and l.position = v.pos
);
